1	import * as forge from "node-forge";
2	import { type Ref } from "vue";
3	import { MessageStatus as Status } from "@/lib/type";
4	import { Role } from "@/lib/enum";
5	import { getApiUrl, persistRenewedToken } from "@/lib/utils";
6	import type { Message } from "@/lib/type";
7	
8	export type CallConfig = {
9	  content: string;
10	  flowId: string;
11	  loadingText?: string;
12	  history?: { role: "user" | "model"; text: string }[];
13	  image?: { mimeType: string; data: string };
14	  /** flow=7（學習規劃探索助手）用：切換底層呼叫的 AI 供應商，例如 "gemini"（預設）、"openai"、"claude" */
15	  model?: string;
16	};
17	
18	export class QuotaExceededError extends Error {
19	  constructor(message: string) {
20	    super(message);
21	    this.name = "QuotaExceededError";
22	  }
23	}
24	
25	/**
26	 * 判斷是不是「AI 服務暫時不可用」類型的錯誤：額度用光、429 限流，或模型過載
27	 * （Gemini 503 UNAVAILABLE／"high demand"、overloaded 等）。這類錯誤不是我們程式的 bug，
28	 * 過一下重試通常就會好，跟其他真正非預期的例外要分開顯示不同訊息，不要每次都用暗示系統
29	 * 故障的「beta 測試版發生錯誤」字樣，使用者也比較知道該重試還是該回報問題。
30	 */
31	const TRANSIENT_AI_ERROR_PATTERN =
32	  /429|503|quota|額度|limit|exceeded|overloaded|unavailable|high demand/i;
33	
34	function isTransientAiError(err: unknown): boolean {
35	  return err instanceof Error && TRANSIENT_AI_ERROR_PATTERN.test(err.message);
36	}
37	
38	export interface AICallContext {
39	  messages: Ref<Message[][]>;
40	  publicKey: string;
41	  fingerprint: Ref<string> | undefined;
42	  jwtToken: Ref<string>;
43	  route: { query: { flow?: string | string[] } };
44	}
45	
46	/**
47	 * 加密簽名
48	 */
49	export async function encryptSignature(
50	  publicKeyBase64: string,
51	  text: string,
52	): Promise<string> {
53	  const publicKeyPem = `-----BEGIN PUBLIC KEY-----\n${publicKeyBase64}\n-----END PUBLIC KEY-----`;
54	  const publicKey = forge.pki.publicKeyFromPem(publicKeyPem);
55	
56	  const encryptedBytes = publicKey.encrypt(text, "RSA-OAEP", {
57	    md: forge.md.sha256.create(),
58	  });
59	
60	  return forge.util.encode64(encryptedBytes);
61	}
62	
63	/**
64	 * 顯示錯誤訊息
65	 */
66	function showErrorMessage(
67	  messages: Ref<Message[][]>,
68	  mIdx: number,
69	  idx: number,
70	  error?: unknown,
71	) {
72	  const content = isTransientAiError(error)
73	    ? "AI 服務目前忙碌（可能是額度限制或模型過載），請稍後再試一次。"
74	    : `beta 測試版發生錯誤，懇請重新登入或撥冗使用 QR code 進行回報`;
75	  messages.value[mIdx][idx] = {
76	    role: Role.Assistant,
77	    content,
78	    timestamp: Date.now(),
79	    status: Status.Error,
80	  };
81	}
82	
83	/**
84	 * 執行 AI 調用（包含簽名生成）
85	 */
86	async function executeAICall(
87	  context: AICallContext,
88	  mIdx: number,
89	  idx: number,
90	  config: CallConfig,
91	): Promise<void> {
92	  const timestamp = Date.now();
93	  const signature = await encryptSignature(
94	    context.publicKey,
95	    `${context.fingerprint?.value} ${timestamp} ${config.flowId}`,
96	  );
97	
98	  // flowId=6（Gemini File Search RAG）、flowId=7（學習規劃探索助手）、
99	  // flowId=8（未來教室設備支援助理）、flowId=9（學習規劃探索助手舊版聊天 UI，跟 7 共用後端）
100	  // 走串流，其他 flow 維持非串流
101	  if (
102	    config.flowId === "6" ||
103	    config.flowId === "7" ||
104	    config.flowId === "8" ||
105	    config.flowId === "9"
106	  ) {
107	    await callStream(context, mIdx, idx, config, signature);
108	  } else {
109	    await callNonStream(context, mIdx, idx, config, signature);
110	  }
111	}
112	
113	/**
114	 * 非流式 AI 調用
115	 */
116	async function callNonStream(
117	  context: AICallContext,
118	  mIdx: number,
119	  idx: number,
120	  config: CallConfig,
121	  signature: string,
122	) {
123	  context.messages.value[mIdx][idx] = {
124	    role: Role.Assistant,
125	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
126	    timestamp: Date.now(),
127	    status: Status.Pending,
128	  };
129	
130	  const res = await fetch(getApiUrl("/api/run?stream=false"), {
131	    method: "POST",
132	    headers: {
133	      "Content-Type": "application/json",
134	      Authorization: signature,
135	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
136	    },
137	    body: JSON.stringify({ input_value: config.content }),
138	  });
139	
140	  persistRenewedToken(res, context.jwtToken);
141	
142	  if (!res.ok) {
143	    const errorText = await res.text();
144	    if (isQuotaErrorText(res.status, errorText)) {
145	      throw new QuotaExceededError(errorText);
146	    }
147	    throw new Error(errorText);
148	  }
149	
150	  const data = await res.json();
151	
152	  if (data.detail) {
153	    const detailStr = String(data.detail);
154	    if (TRANSIENT_AI_ERROR_PATTERN.test(detailStr)) {
155	      throw new QuotaExceededError(detailStr);
156	    }
157	    throw new Error(detailStr);
158	  }
159	
160	  data.outputs?.[0].outputs.forEach((output: any, i: number) => {
161	    context.messages.value[mIdx][idx + i] = {
162	      role: Role.Assistant,
163	      content: output.artifacts.message,
164	      timestamp: Date.now(),
165	      status: Status.End,
166	      source: config.flowId === "5"
167	        ? output.results.message.data.properties.source.source
168	        : "",
169	    };
170	  });
171	}
172	
173	type SseStreamPayload = {
174	  delta?: string;
175	  source?: string;
176	  done?: boolean;
177	  error?: string;
178	};
179	
180	function isQuotaErrorText(status: number, text: string): boolean {
181	  return status === 429 || status === 503 || TRANSIENT_AI_ERROR_PATTERN.test(text);
182	}
183	
184	/** 把一行文字解析成 SSE payload；不是 `data: ` 開頭的行（例如空白分隔行）回傳 null */
185	function parseSseLine(rawLine: string): SseStreamPayload | null {
186	  const line = rawLine.trim();
187	  if (!line.startsWith("data: ")) return null;
188	  return JSON.parse(line.slice("data: ".length));
189	}
190	
191	/** 讀取一個 SSE response body，逐段解析出 payload 陣列（可能因為 chunk 邊界而一次拿到多個或零個） */
192	async function readSseChunk(
193	  reader: ReadableStreamDefaultReader<Uint8Array>,
194	  decoder: TextDecoder,
195	  bufferRef: { value: string },
196	): Promise<{ done: boolean; payloads: SseStreamPayload[] }> {
197	  const { done, value } = await reader.read();
198	  if (done) return { done: true, payloads: [] };
199	
200	  bufferRef.value += decoder.decode(value, { stream: true });
201	  const events = bufferRef.value.split("\n\n");
202	  bufferRef.value = events.pop() ?? ""; // 最後一段可能還不完整，留到下一輪繼續接
203	
204	  const payloads = events
205	    .map(parseSseLine)
206	    .filter((p): p is SseStreamPayload => p !== null);
207	  return { done: false, payloads };
208	}
209	
210	type StreamAccumulator = {
211	  content: string;
212	  source: string;
213	  hasReceivedContent: boolean;
214	};
215	
216	/** 套用單一 SSE payload 到累積狀態，並即時更新畫面上的訊息內容 */
217	function applyStreamPayload(
218	  payload: SseStreamPayload,
219	  acc: StreamAccumulator,
220	  context: AICallContext,
221	  mIdx: number,
222	  idx: number,
223	) {
224	  if (payload.error) throw new Error(payload.error);
225	
226	  if (payload.delta) {
227	    acc.content += payload.delta;
228	    acc.hasReceivedContent = true;
229	    context.messages.value[mIdx][idx] = {
230	      role: Role.Assistant,
231	      content: acc.content,
232	      timestamp: Date.now(),
233	      status: Status.Receiving,
234	    };
235	  }
236	
237	  if (payload.done) acc.source = payload.source ?? "";
238	}
239	
240	/** 讀完整個 SSE response body，過程中即時更新畫面，回傳最終累積狀態 */
241	async function consumeSseStream(
242	  res: Response,
243	  context: AICallContext,
244	  mIdx: number,
245	  idx: number,
246	): Promise<StreamAccumulator> {
247	  const reader = res.body!.getReader();
248	  const decoder = new TextDecoder("utf-8");
249	  const bufferRef = { value: "" };
250	  const acc: StreamAccumulator = { content: "", source: "", hasReceivedContent: false };
251	
252	  while (true) {
253	    const { done, payloads } = await readSseChunk(reader, decoder, bufferRef);
254	    if (done) break;
255	    for (const payload of payloads) {
256	      applyStreamPayload(payload, acc, context, mIdx, idx);
257	    }
258	  }
259	
260	  return acc;
261	}
262	
263	/**
264	 * 串流 AI 調用（flowId=6：Gemini File Search RAG；flowId=7／9：學習規劃探索助手；
265	 * flowId=8：未來教室設備支援助理）
266	 * 後端以 SSE 逐段吐出文字，格式為 `data: {delta, source, done, error}\n\n`
267	 */
268	async function callStream(
269	  context: AICallContext,
270	  mIdx: number,
271	  idx: number,
272	  config: CallConfig,
273	  signature: string,
274	) {
275	  context.messages.value[mIdx][idx] = {
276	    role: Role.Assistant,
277	    content: config.loadingText ?? "吉吉鳥正在尋找答案中",
278	    timestamp: Date.now(),
279	    status: Status.Pending,
280	  };
281	
282	  const res = await fetch(getApiUrl("/api/run?stream=true"), {
283	    method: "POST",
284	    headers: {
285	      "Content-Type": "application/json",
286	      Authorization: signature,
287	      "X-Access-Token": `Bearer ${context.jwtToken.value}`,
288	    },
289	    body: JSON.stringify({
290	      input_value: config.content,
291	      ...(config.history ? { history: config.history } : {}),
292	      ...(config.image ? { image: config.image } : {}),
293	      ...(config.model ? { model: config.model } : {}),
294	    }),
295	  });
296	
297	  persistRenewedToken(res, context.jwtToken);
298	
299	  if (!res.ok || !res.body) {
300	    const errorText = await res.text();
301	    if (isQuotaErrorText(res.status, errorText)) {
302	      throw new QuotaExceededError(errorText);
303	    }
304	    throw new Error(errorText || `串流請求失敗 (${res.status})`);
305	  }
306	
307	  const { content, source, hasReceivedContent } = await consumeSseStream(
308	    res,
309	    context,
310	    mIdx,
311	    idx,
312	  );
313	
314	  context.messages.value[mIdx][idx] = {
315	    role: Role.Assistant,
316	    content: hasReceivedContent
317	      ? content
318	      : "目前找不到與這個問題相關的資料，請確認文件是否已上傳完成，或換個問法再試一次。",
319	    timestamp: Date.now(),
320	    status: Status.End,
321	    source,
322	  };
323	}
324	
325	/**
326	 * AI 調用主函數（包含錯誤處理和額度用光自動切換）
327	 */
328	export async function callAI(
329	  context: AICallContext,
330	  mIdx: number,
331	  idx: number,
332	  config: CallConfig,
333	  _stream: boolean = false,
334	) {
335	  try {
336	    await executeAICall(context, mIdx, idx, config);
337	  } catch (error) {
338	    // 如果是額度用光且當前是 flow 0，自動切換到 flow 1
339	    if (
340	      error instanceof QuotaExceededError &&
341	      config.flowId === "0" &&
342	      !context.route.query.flow
343	    ) {
344	      console.log("額度用光，自動切換到 flow 1");
345	      const fallbackConfig = { ...config, flowId: "1" };
346	      try {
347	        await executeAICall(context, mIdx, idx, fallbackConfig);
348	        return;
349	      } catch (fallbackError) {
350	        // flow 1 也失敗，顯示錯誤
351	        console.error(fallbackError);
352	        showErrorMessage(context.messages, mIdx, idx, fallbackError);
353	        return;
354	      }
355	    }
356	
357	    // 其他錯誤
358	    console.error(error);
359	    showErrorMessage(context.messages, mIdx, idx, error);
360	  }
361	}
