1	using chatai.Core.Config;
2	using chatai.Core.Helper;
3	using chatai.Core.Module;
4	using chatai.Core.Service;
5	using chatai_backend.Attribute;
6	using chatai_backend.Controllers.Base;
7	using chatai_backend.Helpers;
8	using chatai_backend.Model;
9	using Microsoft.AspNetCore.Mvc;
10	using ntu.Common.Utility.Helper;
11	using System.Net.Http.Headers;
12	using System.Text;
13	using System.Text.Json;
14	
15	namespace chatai_backend.Controllers
16	{
17	    [Route("api/run")]
18	    [NeedSignature]
19	    public class RunController : BaseApiController
20	    {
21	        /// <summary>
22	        /// flowId=6 走 Gemini File Search RAG，不再 proxy 到 Langflow
23	        /// </summary>
24	        private const int GeminiFlowIndex = 6;
25	
26	        /// <summary>
27	        /// flowId=7：學習規劃探索助手，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
28	        /// </summary>
29	        private const int AdvisingFlowIndex = 7;
30	
31	        /// <summary>
32	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
33	        /// </summary>
34	        private const int ClassroomFaqFlowIndex = 8;
35	
36	        /// <summary>
37	        /// flowId=9：舊版「學習規劃探索助手」通用聊天 UI，跟 flowId=7（explore 沉浸式體驗）
38	        /// 共用同一個 AdvisingChatService，只是前端呈現方式不同（一個是聊天氣泡、一個是沉浸式體驗）。
39	        /// </summary>
40	        private const int AdvisingChatUiFlowIndex = 9;
41	
42	        private readonly IHttpClientFactory _httpClientFactory;
43	        private readonly AppSettingConfig _appSetting;
44	        private readonly SignatureContext _signatureContext;
45	        private readonly IGeminiFileSearchService _geminiService;
46	        private readonly IAdvisingChatService _advisingService;
47	        private readonly IClassroomFaqChatService _classroomFaqService;
48	        private readonly IChataiModule _chataiModule;
49	        private readonly ILogger<RunController> _logger;
50	
51	        public RunController(
52	            IHttpClientFactory httpClientFactory,
53	            AppSettingConfig appSetting,
54	            SignatureContext signatureContext,
55	            IGeminiFileSearchService geminiService,
56	            IAdvisingChatService advisingService,
57	            IClassroomFaqChatService classroomFaqService,
58	            IChataiModule chataiModule,
59	            ILogger<RunController> logger)
60	        {
61	            _httpClientFactory = httpClientFactory;
62	            _appSetting = appSetting;
63	            _signatureContext = signatureContext;
64	            _geminiService = geminiService;
65	            _advisingService = advisingService;
66	            _classroomFaqService = classroomFaqService;
67	            _chataiModule = chataiModule;
68	            _logger = logger;
69	        }
70	
71	        [HttpGet]
72	        public IActionResult Get()
73	        {
74	            return Content("");
75	        }
76	
77	        [HttpPost]
78	        public async Task<IActionResult> Post([FromBody] JsonElement body)
79	        {
80	            var apiFlowIndex = _signatureContext.apiFlow;
81	
82	            if (apiFlowIndex == GeminiFlowIndex)
83	                return await RunGeminiFlow(body);
84	
85	            // flowId=7（explore 沉浸式體驗）的對話紀錄由後端管理，見 RunAdvisingExploreFlow；
86	            // flowId=9（舊版通用聊天 UI）維持原本前端整包送 history 的無狀態走法，見 RunAdvisingFlow。
87	            if (apiFlowIndex == AdvisingFlowIndex)
88	                return await RunAdvisingExploreFlow(body);
89	
90	            if (apiFlowIndex == AdvisingChatUiFlowIndex)
91	                return await RunAdvisingFlow(body);
92	
93	            if (apiFlowIndex == ClassroomFaqFlowIndex)
94	                return await RunClassroomFaqFlow(body);
95	
96	            var apiUrl = _appSetting.ApiUrl;
97	            var apiKey = _appSetting.ApiKey;
98	            var flowIds = _appSetting.FlowIds;
99	
100	            if (string.IsNullOrEmpty(apiUrl)
101	                || string.IsNullOrEmpty(apiKey)
102	                || flowIds == null
103	                || !flowIds.Any())
104	                throw new Exception("Missing configuration values.");
105	
106	            //var stream = HttpContext.Request.Query["stream"].ToNullString().ToBoolean().ToString().ToLower();
107	
108	            if (flowIds.Count() <= apiFlowIndex)
109	                return BadRequest("Invalid API flow index.");
110	
111	            var flowId = flowIds.Skip(apiFlowIndex).First();
112	
113	            var targetUrl = $"{apiUrl}/api/v1/run/{flowId}";//?stream={stream}
114	
115	            using var client = _httpClientFactory.CreateClient("NoSsl");
116	            var json = body.GetRawText();
117	            var jsonBytes = Encoding.UTF8.GetBytes(json);
118	            using var content = new ByteArrayContent(jsonBytes)
119	            {
120	                Headers =
121	                {
122	                    ContentType = new MediaTypeHeaderValue("application/json"),
123	                    ContentLength = jsonBytes.Length
124	                }
125	            };
126	
127	            var requestMessage = new HttpRequestMessage(HttpMethod.Post, targetUrl)
128	            {
129	                Content = content
130	            };
131	
132	            requestMessage.Content?.Headers.TryAddWithoutValidation("x-api-key", apiKey);
133	
134	            var response = await client.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead);
135	            var responseBody = await response.Content.ReadAsStringAsync();
136	
137	            Response.Headers.Append("x-flow", $"{apiFlowIndex}");
138	
139	            return Content(responseBody, response.Content.Headers.ContentType?.ToString() ?? "application/json");
140	        }
141	
142	        /// <summary>
143	        /// flowId=6：改用 Gemini File Search 做 RAG，以 SSE 串流方式即時把答案文字吐給前端，
144	        /// 每個 event 是一行 `data: {...}\n\n`，格式為 { delta, source, done, error }。
145	        /// </summary>
146	        private async Task<IActionResult> RunGeminiFlow(JsonElement body)
147	        {
148	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
149	            if (string.IsNullOrEmpty(userId))
150	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
151	
152	            if (!body.TryGetProperty("input_value", out var inputValueEl))
153	                return BadRequest("Missing input_value.");
154	
155	            var inputValue = inputValueEl.GetString() ?? "";
156	
157	            Response.ContentType = "text/event-stream";
158	            Response.Headers.Append("Cache-Control", "no-cache");
159	            Response.Headers.Append("x-flow", $"{GeminiFlowIndex}");
160	
161	            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
162	            {
163	                var payload = JsonSerializer.Serialize(new
164	                {
165	                    delta = chunk.Delta,
166	                    source = chunk.Source,
167	                    done = chunk.Done,
168	                    error = chunk.Error,
169	                });
170	                await Response.WriteAsync($"data: {payload}\n\n");
171	                await Response.Body.FlushAsync();
172	            }
173	
174	            return new EmptyResult();
175	        }
176	
177	        /// <summary>
178	        /// flowId=9：舊版「學習規劃探索助手」通用聊天 UI，直接呼叫 Gemini 做多輪對話，以 SSE 串流方式
179	        /// 即時把答案文字吐給前端。這條路徑維持原本無狀態設計，多輪對話紀錄由前端透過 body.history
180	        /// 每次完整帶入——跟 flowId=7（見 RunAdvisingExploreFlow）不同，flowId=9 沒有走 exploration
181	        /// 資料表持久化。
182	        /// </summary>
183	        private async Task<IActionResult> RunAdvisingFlow(JsonElement body)
184	        {
185	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
186	            if (string.IsNullOrEmpty(userId))
187	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
188	
189	            if (!body.TryGetProperty("input_value", out var inputValueEl))
190	                return BadRequest("Missing input_value.");
191	
192	            var inputValue = inputValueEl.GetString() ?? "";
193	
194	            var history = new List<(string Role, string Text)>();
195	            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
196	            {
197	                foreach (var item in historyEl.EnumerateArray())
198	                {
199	                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
200	                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
201	                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
202	                        continue;
203	                    history.Add((role, text));
204	                }
205	            }
206	
207	            // 前端透過 ?model= 帶入（例如 /?flow=7&model=claude），對應 body.model；未帶則預設 gemini
208	            var model = "gemini";
209	            if (body.TryGetProperty("model", out var modelEl) && modelEl.ValueKind == JsonValueKind.String)
210	            {
211	                var requestedModel = modelEl.GetString();
212	                if (!string.IsNullOrWhiteSpace(requestedModel))
213	                    model = requestedModel;
214	            }
215	
216	            Response.ContentType = "text/event-stream";
217	            Response.Headers.Append("Cache-Control", "no-cache");
218	            Response.Headers.Append("x-flow", $"{AdvisingFlowIndex}");
219	
220	            await foreach (var chunk in _advisingService.QueryStreamAsync(inputValue, history, model))
221	            {
222	                var payload = JsonSerializer.Serialize(new
223	                {
224	                    delta = chunk.Delta,
225	                    source = chunk.Source,
226	                    done = chunk.Done,
227	                    error = chunk.Error,
228	                });
229	                await Response.WriteAsync($"data: {payload}\n\n");
230	                await Response.Body.FlushAsync();
231	            }
232	
233	            return new EmptyResult();
234	        }
235	
236	        /// <summary>
237	        /// flowId=7：學習規劃探索助手（explore 沉浸式體驗），直接呼叫 Gemini 做多輪對話，以 SSE 串流
238	        /// 方式即時把答案文字吐給前端。跟 flowId=9（RunAdvisingFlow）不同，這裡對話紀錄由後端管理：
239	        /// 前端只帶 exploration_id + input_value，history 從 [dbo].[exploration] 讀出來，串流結束後
240	        /// 把這輪（使用者輸入＋AI 完整回覆）append 回去存下。這樣前端沒辦法透過竄改 history 操控
241	        /// Critical Conversation State Rule 判斷的階段，且不用每輪都整包重送歷史。
242	        /// accountName 只用來核對 exploration 的歸屬，不會傳進 _advisingService.QueryStreamAsync——
243	        /// 那個方法一直以來就只吃 question + history 兩個純文字參數，SSO 身份資訊不會流向 AI。
244	        /// </summary>
245	        private async Task<IActionResult> RunAdvisingExploreFlow(JsonElement body)
246	        {
247	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
248	            if (string.IsNullOrEmpty(userId))
249	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
250	
251	            if (!body.TryGetProperty("exploration_id", out var explorationIdEl) ||
252	                !Guid.TryParse(explorationIdEl.GetString(), out var explorationId))
253	                return BadRequest("Missing or invalid exploration_id.");
254	
255	            if (!body.TryGetProperty("input_value", out var inputValueEl))
256	                return BadRequest("Missing input_value.");
257	
258	            var inputValue = inputValueEl.GetString() ?? "";
259	
260	            // 空白內容不能往下走：這輪成功後會被原封不動存進 history_json（見下方 history.Add），
261	            // Claude/Gemini 的多輪對話 API 都不接受空字串的訊息內容，一旦存進去，這筆探索之後
262	            // 每輪都要重送整段 history，會永久卡在同一個錯誤（見 ExplorationHistoryJson.Parse
263	            // 的自動過濾說明——那是幫已經中招的舊資料復原，這裡是從源頭擋掉新的個案）。
264	            if (string.IsNullOrWhiteSpace(inputValue))
265	                return BadRequest("input_value 不可為空白。");
266	
267	            var record = _chataiModule.GetExplorationById(explorationId);
268	            if (record == null || record.is_del || record.account_name != userId)
269	                return NotFound("找不到探索紀錄，或這筆紀錄不屬於目前登入的使用者。");
270	
271	            var history = ExplorationHistoryJson.Parse(record.history_json);
272	
273	            // 前端透過 ?model= 帶入（例如 /?flow=7&model=claude），對應 body.model；未帶則預設 gemini
274	            var model = "gemini";
275	            if (body.TryGetProperty("model", out var modelEl) && modelEl.ValueKind == JsonValueKind.String)
276	            {
277	                var requestedModel = modelEl.GetString();
278	                if (!string.IsNullOrWhiteSpace(requestedModel))
279	                    model = requestedModel;
280	            }
281	
282	            Response.ContentType = "text/event-stream";
283	            Response.Headers.Append("Cache-Control", "no-cache");
284	            Response.Headers.Append("x-flow", $"{AdvisingFlowIndex}");
285	
286	            var replyBuilder = new StringBuilder();
287	            var streamFailed = false;
288	
289	            await foreach (var chunk in _advisingService.QueryStreamAsync(inputValue, history, model))
290	            {
291	                if (!string.IsNullOrEmpty(chunk.Delta))
292	                    replyBuilder.Append(chunk.Delta);
293	                if (!string.IsNullOrEmpty(chunk.Error))
294	                    streamFailed = true;
295	
296	                var payload = JsonSerializer.Serialize(new
297	                {
298	                    delta = chunk.Delta,
299	                    source = chunk.Source,
300	                    done = chunk.Done,

300	                    done = chunk.Done,
301	                    error = chunk.Error,
302	                });
303	                await Response.WriteAsync($"data: {payload}\n\n");
304	                await Response.Body.FlushAsync();
305	            }
306	
307	            // 串流中途失敗（額度/限流等）就不要把這輪寫回歷史，避免存進一段不完整或空白的 AI 回覆，
308	            // 讓使用者下次重送時還是接在最後一個成功的完整回合之後。
309	            if (!streamFailed && replyBuilder.Length > 0)
310	            {
311	                history.Add(("user", inputValue));
312	                history.Add(("model", replyBuilder.ToString()));
313	                _chataiModule.UpdateExplorationHistory(explorationId, userId, ExplorationHistoryJson.Serialize(history), DateTime.Now);
314	            }
315	
316	            return new EmptyResult();
317	        }
318	
319	        /// <summary>
320	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini 做多輪對話（可附加一張照片做單次視覺問答），
321	        /// 以 SSE 串流方式即時把答案文字吐給前端。多輪對話紀錄由前端透過 body.history 每次完整帶入。
322	        /// </summary>
323	        private async Task<IActionResult> RunClassroomFaqFlow(JsonElement body)
324	        {
325	            var ipWhitelist = _appSetting.ClassroomFaqIpWhitelist;
326	            if (ipWhitelist is { Count: > 0 })
327	            {
328	                var clientIp = IpHelper.GetClientIpAddress(HttpContext);
329	                if (!IpHelper.IsMatchIpAddress(new[] { clientIp }, ipWhitelist))
330	                {
331	                    _logger.LogWarning("flow=8 拒絕來源 IP {ClientIp} 存取。", clientIp);
332	                    return StatusCode(StatusCodes.Status403Forbidden, "此功能僅開放特定網路環境使用，請洽數位學習中心。");
333	                }
334	            }
335	
336	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
337	            if (string.IsNullOrEmpty(userId))
338	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
339	
340	            if (!body.TryGetProperty("input_value", out var inputValueEl))
341	                return BadRequest("Missing input_value.");
342	
343	            var inputValue = inputValueEl.GetString() ?? "";
344	
345	            var history = new List<(string Role, string Text)>();
346	            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
347	            {
348	                foreach (var item in historyEl.EnumerateArray())
349	                {
350	                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
351	                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
352	                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
353	                        continue;
354	                    history.Add((role, text));
355	                }
356	            }
357	
358	            (string MimeType, string Base64Data)? image = null;
359	            if (body.TryGetProperty("image", out var imageEl) && imageEl.ValueKind == JsonValueKind.Object)
360	            {
361	                var mimeType = imageEl.TryGetProperty("mimeType", out var mimeEl) ? mimeEl.GetString() : null;
362	                var data = imageEl.TryGetProperty("data", out var dataEl) ? dataEl.GetString() : null;
363	                if (!string.IsNullOrEmpty(mimeType) && !string.IsNullOrEmpty(data))
364	                    image = (mimeType, data);
365	            }
366	
367	            Response.ContentType = "text/event-stream";
368	            Response.Headers.Append("Cache-Control", "no-cache");
369	            Response.Headers.Append("x-flow", $"{ClassroomFaqFlowIndex}");
370	
371	            await foreach (var chunk in _classroomFaqService.QueryStreamAsync(inputValue, history, image))
372	            {
373	                var payload = JsonSerializer.Serialize(new
374	                {
375	                    delta = chunk.Delta,
376	                    source = chunk.Source,
377	                    done = chunk.Done,
378	                    error = chunk.Error,
379	                });
380	                await Response.WriteAsync($"data: {payload}\n\n");
381	                await Response.Body.FlushAsync();
382	            }
383	
384	            return new EmptyResult();
385	        }
386	    }
387	}
