1	import { createApp, inject } from "vue";
2	import { createRouter, createWebHistory } from "vue-router";
3	import { VueQueryPlugin } from "@tanstack/vue-query";
4	import { LocalStorageKey } from "@/lib/constant";
5	import App from "@/App.vue";
6	import "@/assets/index.css";
7	import { jwtDecode } from "jwt-decode";
8	import { JwtToken } from "@/lib/type";
9	
10	const app = createApp(App);
11	app.use(VueQueryPlugin);
12	
13	try {
14	  const jwtToken = localStorage.getItem(LocalStorageKey.JWT_TOKEN);
15	  // Check if the token exists
16	  if (!jwtToken) throw new Error("No JWT token found in local storage");
17	  const user = jwtDecode<JwtToken>(jwtToken);
18	  // Check if the token is expired (allowing a grace period of 8 hours)
19	  if (user?.iat && Math.floor(Date.now() / 1000) - user.iat > 8 * 60 * 60)
20	    throw new Error("Token expired");
21	  app.provide("user", user);
22	} catch (error) {
23	  localStorage.removeItem(LocalStorageKey.JWT_TOKEN);
24	  app.provide("user", null);
25	}
26	
27	const routes = [
28	  { path: "/", component: () => import("@/views/HomeView.vue") },
29	  { path: "/help", component: () => import("@/views/help/HelpPage.vue") },
30	  { path: "/docs", component: () => import("@/views/docs/DocsPage.vue") },
31	  { path: "/login", component: () => import("@/views/login/LoginPage.vue") },
32	  { path: "/rating", component: () => import("@/views/rating/RatingPage.vue") },
33	];
34	
35	const router = createRouter({
36	  history: createWebHistory(),
37	  routes,
38	});
39	
40	router.beforeEach((to) => {
41	  const isAuthenticated = inject("user") !== null;
42	  if (to.path === "/login" && isAuthenticated) return "/";
43	  if (to.path !== "/login" && !isAuthenticated) return "/login";
44	  // flow=7（學習規劃探索助手）改用獨立部署的沉浸式體驗，整頁導出去，
45	  // 不在這顆共用 SPA 裡渲染，避免動到 MainPage/InputBlock/ChatProvider 影響其他 flow。
46	  if (to.path === "/" && isAuthenticated && to.query.flow === "7") {
47	    const exploreUrl = import.meta.env.VITE_EXPLORE_URL;
48	    if (exploreUrl) {
49	      const token = localStorage.getItem(LocalStorageKey.JWT_TOKEN) ?? "";
50	      const params = new URLSearchParams({ token });
51	      // 例如 ?flow=7&model=claude 一併轉發過去，讓 app-vue 那邊沿用同一套模型切換能力
52	      if (to.query.model) params.set("model", String(to.query.model));
53	      window.location.href = `${exploreUrl.replace(/\/$/, "")}/?${params.toString()}`;
54	      return false;
55	    }
56	  }
57	  if (to.path === "/" && isAuthenticated && !to.query.flow) {
58	    return { path: "/", query: { ...to.query, flow: "6" } };
59	  }
60	  return true;
61	});
62	
63	app.use(router).mount("#app");
