202	async function send(content: string, flowId?: string) {
203	  // 1. 創建用戶消息（附加照片時在訊息內容加註提示，讓歷史紀錄也看得出來曾經附圖）
204	  const pendingImage = attachedImage.value ?? undefined;
205	  const displayContent = pendingImage ? `${content}\n📎 已附加照片` : content;
206	  const messageIndex = addUserMessage(displayContent);
207	  clearAttachedImage();
208	
209	  // flow=3（簡易模式）或 flow=6（Gemini File Search RAG）時，跳過 QA 搜尋，直接呼叫 AI
210	  const routeFlow = route.query.flow?.toString();
211	  if (routeFlow && SIMPLE_MODE_FLOW_IDS.includes(routeFlow)) {
212	    await callAIWrapper(messageIndex, content, routeFlow, undefined, pendingImage);
213	    return;
214	  }
215	
216	  // 2. 搜索 QA
217	  const qaResults = await searchQA(content);
218	  // 3. 處理 QA 結果
219	  const shouldShowQAList = handleQAResults(qaResults, messageIndex, content);
220	  if (shouldShowQAList) return; // 顯示 QA 列表，結束流程
221	  // 4. 調用 AI
222	  await callAIWrapper(messageIndex, content, flowId, undefined, pendingImage);
223	}
