225	/**
226	 * 處理 QA 搜尋結果
227	 * @returns true 如果顯示了 QA 列表，false 如果應該繼續調用 AI
228	 */
229	function handleQAResults(
230	  qaResults: QAItem[] | null,
231	  messageIndex: number,
232	  originalContent: string,
233	): boolean {
234	  // 沒有 QA 結果，清空記錄並繼續呼叫 AI
235	  if (!qaResults || qaResults.length === 0) {
236	    previousQAIds.value = null;
237	    return false;
238	  }
239	
240	  const limitedResults = qaResults.slice(0, 5);
241	  const currentIds = limitedResults
242	    .map((item) => item.id)
243	    .filter((id): id is number => id !== undefined);
244	
245	  // 如果這次的 QA 結果和上次一樣，改用 AI 回覆
246	  if (
247	    previousQAIds.value &&
248	    currentIds.length > 0 &&
249	    compareQAIds(currentIds, previousQAIds.value)
250	  ) {

250	  ) {
251	    // 結果相同，不更新 previousQAIds，繼續呼叫 AI
252	    return false;
253	  }
254	
255	  // 結果不同或沒有上一次結果，顯示 QA 清單
256	  previousQAIds.value = currentIds.length > 0 ? currentIds : null;
257	
258	  messages.value[messageIndex][1] = {
259	    role: Role.Assistant,
260	    content: "吉吉鳥猜你是想要問",
261	    timestamp: Date.now(),
262	    status: Status.End,
263	    qa: limitedResults,
264	    question: originalContent,
265	  };
266	
267	  toChatBottom({ behavior: "smooth" });
268	  return true;
269	}
